  '--headless','--disable-gpu','--no-first-run','--disable-background-networking',
  '--remote-debugging-port=0','--user-data-dir='+profile, 'about:blank'
], {windowsHide:true,stdio:'ignore'})
let ws
try {
  let port
  for (let i=0;i<100 && !port;i++) {
