  await key('Enter','Enter',13)
  const selected = () => evaluate("document.activeElement.getAttribute('aria-current') === 'true' && document.querySelector('[aria-labelledby=park-details-heading] p').textContent.includes(document.activeElement.querySelector('.park-list-name').textContent)")
  assert.ok(await selected(),'Enter selects the focused park and updates details')
  await key('Tab','Tab',9)
  assert.ok(await evaluate("document.activeElement === document.querySelectorAll('.park-list-button')[1]"))
  await key(' ','Space',32)
  assert.ok(await selected(),'Space selects the next park and updates details')
  assert.ok(await evaluate("[...document.querySelectorAll('.park-list-button')].every(b=>b.getBoundingClientRect().height>=44)"))
  assert.equal(await evaluate("[...document.querySelectorAll('.park-list-button')].find(b=>b.innerText.includes('Highland Dog Park')).innerText"),'Highland Dog Park')
  const tree = await send('Accessibility.getFullAXTree')
  const first = await evaluate("document.querySelector('.park-list-button').innerText.split(/\\\\s+/).join(' ')")
  assert.ok(tree.nodes.some(n=>n.role?.value==='button' && n.name?.value===first),'Chrome accessible name separates name and address')
  assert.ok(await evaluate("document.querySelector('.park-list-name').textContent = 'A'.repeat(160); document.documentElement.scrollWidth === innerWidth && document.querySelector('.park-list-button').scrollWidth <= document.querySelector('.park-list-button').clientWidth"))
  console.log('Chrome production check passed at 375px: Tab, Enter, Space, details selection, focus outline, accessible name, touch targets, missing address and long-name wrapping.')
